def ispar(x):
    stack = []
    matching_bracket = {')': '(', '}': '{', ']': '['}
    for char in x:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if stack == [] or matching_bracket[char] != stack.pop():
                return False
        else:
            continue
    return stack == []

import sys
input = sys.stdin.read().strip()
print("balanced" if ispar(input) else "not balanced")
